Future<dynamic> communityAction(String action,[Map<String,dynamic> data=const {}])async=>soveraClient.rpc('sovera_app_action',params:{'p_action':action,'p_data':data});
String requestId(){final r=Random.secure();final b=List<int>.generate(16,(_)=>r.nextInt(256));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;final h=b.map((v)=>v.toRadixString(16).padLeft(2,'0')).join();return '${h.substring(0,8)}-${h.substring(8,12)}-${h.substring(12,16)}-${h.substring(16,20)}-${h.substring(20)}';}
String countryFlag(dynamic value){final code=(value??'').toString().trim().toUpperCase();if(!RegExp(r'^[A-Z]{2}$').hasMatch(code))return '';return String.fromCharCodes(code.codeUnits.map((v)=>v+127397));}
String communityError(Object error)=>error is PostgrestException?error.message:'Could not connect. Please retry.';
void communityNotice(BuildContext context,String text)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(text)));

class ProfileSetupPage extends StatefulWidget{
 final Map<String,dynamic> profile;final VoidCallback? onSaved;
 const ProfileSetupPage({super.key,required this.profile,this.onSaved});
 @override State<ProfileSetupPage> createState()=>_ProfileSetupPageState();
}
class _ProfileSetupPageState extends State<ProfileSetupPage>{
 late final TextEditingController name,bio,location,country;String? avatar,error;bool busy=false;
 @override void initState(){super.initState();name=TextEditingController(text:widget.profile['display_name'] as String?);bio=TextEditingController(text:widget.profile['bio'] as String?);location=TextEditingController(text:widget.profile['location'] as String?);country=TextEditingController(text:widget.profile['country'] as String?);avatar=widget.profile['avatar_url'] as String?;}
 @override void dispose(){name.dispose();bio.dispose();location.dispose();country.dispose();super.dispose();}
 Future<void> photo()async{if(busy)return;setState(()=>busy=true);try{final file=await ImagePicker().pickImage(source:ImageSource.gallery,maxWidth:512,maxHeight:512,imageQuality:85);if(file==null)return;final bytes=await file.readAsBytes();if(bytes.length>10485760)throw StateError('Choose an image under 10 MB.');final codec=await ui.instantiateImageCodec(bytes,targetWidth:512);final frame=await codec.getNextFrame();final data=await frame.image.toByteData(format:ui.ImageByteFormat.png);frame.image.dispose();codec.dispose();if(data==null||data.lengthInBytes>2097152)throw StateError('Choose a smaller image.');final path='${widget.profile['id']}/avatar.png';await soveraClient.storage.from('sovera-profile-photos').uploadBinary(path,data.buffer.asUint8List(),fileOptions:const FileOptions(contentType:'image/png',upsert:true));final url=soveraClient.storage.from('sovera-profile-photos').getPublicUrl(path);if(mounted)setState(()=>avatar='$url?v=${DateTime.now().millisecondsSinceEpoch}');}catch(e){if(mounted)setState(()=>error=e is StateError?e.message.toString():communityError(e));}finally{if(mounted)setState(()=>busy=false);}}
 Future<void> save()async{if(busy)return;if(name.text.trim().isEmpty){setState(()=>error='Enter your display name.');return;}final code=country.text.trim().toUpperCase();if(code.isNotEmpty&&!RegExp(r'^[A-Z]{2}$').hasMatch(code)){setState(()=>error='Use a two-letter country code, for example BD or OM.');return;}setState((){busy=true;error=null;});try{final row=await soveraClient.from('sovera_profiles').update({'display_name':name.text.trim(),'bio':bio.text.trim(),'location':location.text.trim(),'country':code,'avatar_url':avatar,'onboarded':true}).eq('id',widget.profile['id'] as String).select().single();if(mounted){widget.profile.addAll(row);if(widget.onSaved!=null){widget.onSaved!();}else{Navigator.pop(context,row);}}}catch(e){if(mounted)setState(()=>error=communityError(e));}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.profile['onboarded']==true?'Edit profile':'Complete your profile')),body:ListView(padding:const EdgeInsets.all(22),children:[Center(child:InkWell(onTap:busy?null:photo,child:avatar==null?const BrandLogo(size:100):ClipOval(child:Image.network(avatar!,width:100,height:100,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const BrandLogo(size:100))))),TextButton.icon(onPressed:busy?null:photo,icon:const Icon(Icons.photo_library_outlined),label:const Text('Choose profile photo')),const Text('Profile photos are visible to other users. Location is optional; do not enter a private street address.',style:TextStyle(color:Colors.white60,fontSize:12)),TextField(controller:name,maxLength:40,decoration:const InputDecoration(labelText:'Display name')),TextField(controller:bio,maxLength:150,decoration:const InputDecoration(labelText:'Bio')),TextField(controller:location,maxLength:100,decoration:const InputDecoration(labelText:'City / location (optional)')),TextField(controller:country,maxLength:2,textCapitalization:TextCapitalization.characters,decoration:const InputDecoration(labelText:'Country code · BD, OM, SA…')),if(error!=null)Text(error!,style:const TextStyle(color:Colors.redAccent)),FilledButton(onPressed:busy?null:save,child:Text(busy?'Saving…':'Save profile'))]));
}

class AccountWalletCard extends StatefulWidget{
