 @override Widget build(BuildContext context)=>Glass(tint:gold,child:Column(children:[ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.account_balance_wallet_rounded,color:gold),title:const Text('Wallet'),subtitle:Text('Coins $coins  ·  Diamonds $diamonds'),onTap:()async{widget.onOpen();},trailing:IconButton(tooltip:'Refresh balance',onPressed:load,icon:const Icon(Icons.refresh_rounded)))]));
}

