class DiamondExchange extends StatefulWidget{const DiamondExchange({super.key});@override State<DiamondExchange> createState()=>_DiamondExchangeState();}
class _DiamondExchangeState extends State<DiamondExchange>{
 final amount=TextEditingController();Map<String,dynamic>? settings;String? error;bool busy=false;String? pendingId,pendingAmount;
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final s=await soveraClient.from('sovera_system_settings').select().single();if(mounted)setState(()=>settings=s);}catch(e){if(mounted)setState(()=>error=communityError(e));}}
 @override void dispose(){amount.dispose();super.dispose();}
 Future<void> exchange()async{if(busy)return;final n=int.tryParse(amount.text);if(n==null||n<1)return;if(pendingAmount!=amount.text){pendingId=requestId();pendingAmount=amount.text;}setState(()=>busy=true);try{final result=await communityAction('exchange',{'diamonds':n,'request_id':pendingId});if(mounted){communityNotice(context,'Exchange recorded: ${result['coins']} Coins');Navigator.pop(context);}}catch(e){if(mounted)setState(()=>error=communityError(e));}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Diamond exchange')),body:ListView(padding:const EdgeInsets.all(22),children:[Text(settings==null?'Loading exchange settings…':'${settings!['exchange_diamonds']} Diamonds = ${settings!['exchange_coins']} Coins',style:const TextStyle(fontSize:20)),if(settings?['exchange_enabled']!=true)const Text('Exchange is currently disabled.'),TextField(controller:amount,keyboardType:TextInputType.number,readOnly:busy,decoration:const InputDecoration(labelText:'Diamonds to exchange')),const SizedBox(height:16),if(error!=null)Text(error!),FilledButton(onPressed:busy||settings?['exchange_enabled']!=true?null:exchange,child:Text(busy?'Processing…':'Confirm exchange'))]));
}

class SavedMoments extends StatefulWidget{const SavedMoments({super.key});@override State<SavedMoments> createState()=>_SavedMomentsState();}
class _SavedMomentsState extends State<SavedMoments>{
 List<dynamic>? posts;String? error;bool busy=false;
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final rows=await communityAction('moments');if(mounted)setState((){posts=rows as List<dynamic>;error=null;});}catch(e){if(mounted)setState(()=>error=communityError(e));}}
 Future<String?> text(String title,int max)=>showDialog<String>(context:context,builder:(context)=>_CommunityTextDialog(title:title,max:max));
 Future<void> post()async{if(busy)return;final body=await text('Write a moment',2000);if(body==null||!mounted)return;setState(()=>busy=true);try{await communityAction('moment.create',{'body':body});await load();}catch(e){if(mounted)setState(()=>error=communityError(e));}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[Expanded(child:FilledButton.icon(onPressed:busy?null:post,icon:const Icon(Icons.edit_rounded),label:const Text('Write a moment'))),IconButton(tooltip:'Refresh feed',onPressed:load,icon:const Icon(Icons.refresh_rounded))]),if(error!=null)Text(error!),if(posts==null&&error==null)const LinearProgressIndicator(),if(posts?.isEmpty==true)const Padding(padding:EdgeInsets.all(18),child:Text('No community posts yet.')),for(final p in posts??[])Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${p['display_name']} ${countryFlag(p['country'])} · ${p['uid']}',style:const TextStyle(fontWeight:FontWeight.bold)),const SizedBox(height:12),Text(p['body'].toString()),const SizedBox(height:8),Row(children:[TextButton(onPressed:()async{final reason=await text('Report this post',1000);if(reason==null)return;try{await communityAction('report.create',{'kind':'moment','target':p['id'],'reason':reason});if(context.mounted)communityNotice(context,'Report submitted.');}catch(e){if(context.mounted)communityNotice(context,communityError(e));}},child:const Text('Report')),if(p['user_id']==soveraClient.auth.currentUser?.id)TextButton(onPressed:()async{try{await communityAction('moment.delete',{'id':p['id']});await load();}catch(e){if(context.mounted)communityNotice(context,communityError(e));}},child:const Text('Delete my post'))])])))]);
}
