class ConnectionsPage extends StatefulWidget{final String kind;const ConnectionsPage({super.key,required this.kind});@override State<ConnectionsPage> createState()=>_ConnectionsPageState();}
class _ConnectionsPageState extends State<ConnectionsPage>{
 List<dynamic>? rows;String? error;bool busy=false;
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final r=await communityAction('connections');if(mounted)setState(()=>rows=r as List<dynamic>);}catch(e){if(mounted)setState(()=>error=communityError(e));}}
 Future<void> invite()async{final uid=await showDialog<String>(context:context,builder:(_)=>const _CommunityTextDialog(title:'Enter 8-digit user ID',max:8));if(uid==null||busy)return;setState(()=>busy=true);try{await communityAction('connection.request',{'uid':uid,'kind':widget.kind=='friend'?'friend':'cp'});await load();}catch(e){if(mounted)setState(()=>error=communityError(e));}finally{if(mounted)setState(()=>busy=false);}}
