 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.kind=='friend'?'Friendship':widget.kind=='love'?'Love & CP':'Couple space'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh_rounded))]),body:ListView(padding:const EdgeInsets.all(20),children:[Text(widget.kind=='friend'?'Friend requests become active after the recipient accepts.':'A CP connection requires both people to agree. Each account can have one active CP partner.'),FilledButton.icon(onPressed:busy?null:invite,icon:const Icon(Icons.person_add_alt_1_rounded),label:Text(widget.kind=='friend'?'Add friend by ID':'Invite CP partner')),if(error!=null)Text(error!),if(rows==null&&error==null)const LinearProgressIndicator(),for(final r in (rows??[]).where((r)=>r['kind']==(widget.kind=='friend'?'friend':'cp')))Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${r['display_name']} · ${r['uid']}',style:const TextStyle(fontWeight:FontWeight.bold)),Text('${r['status']} · ${r['sender_id']==soveraClient.auth.currentUser?.id?'Sent by you':'Received'}'),Wrap(children:[if(r['status']=='pending'&&r['receiver_id']==soveraClient.auth.currentUser?.id)TextButton(onPressed:()=>respond(r,'accept'),child:const Text('Accept')),TextButton(onPressed:()=>respond(r,'end'),child:Text(r['status']=='accepted'?'End connection':'Decline / cancel'))])]))),if(widget.kind=='love')const Padding(padding:EdgeInsets.only(top:20),child:Text('Love gift points and partner gift history need the gift settlement service. No points are generated from previews.'))]));
}

final communityRevision=ValueNotifier<int>(0);
class GrantedProfileFrame extends StatelessWidget{
 final dynamic uid;final double size;final Widget child;const GrantedProfileFrame({super.key,required this.uid,required this.size,required this.child});
 @override Widget build(BuildContext context)=>ValueListenableBuilder<int>(valueListenable:communityRevision,builder:(context,revision,_)=>FutureBuilder<dynamic>(future:uid==null?Future<dynamic>.value():communityAction('frame.lookup',{'uid':uid}),builder:(context,snapshot){final data=snapshot.data;final raw=data is Map?data['asset_url']?.toString():null;final url=raw!=null&&Uri.tryParse(raw)?.scheme=='https'?raw:null;return SizedBox(width:size,height:size,child:Stack(alignment:Alignment.center,children:[child,if(url!=null)IgnorePointer(child:Image.network(url,width:size,height:size,fit:BoxFit.contain,errorBuilder:(_,__,___)=>const SizedBox.shrink()))]));}));
}
